with card_content(display_order, question_text, question_translation, answer_examples) as (
  values
    (101, 'If you could live anywhere in the world, where would you live?', 'Se você pudesse morar em qualquer lugar do mundo, onde moraria?', '[{"answer":"I''d live in Portugal.","translation":"Eu moraria em Portugal.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I''d choose Canada.","translation":"Eu escolheria o Canadá.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I''d love to live in Italy.","translation":"Eu adoraria morar na Itália.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I think I''d stay in Brazil, but near the beach.","translation":"Acho que eu ficaria no Brasil, mas perto da praia.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I''d probably choose a safe, walkable city with good weather and plenty of cultural activities.","translation":"Eu provavelmente escolheria uma cidade segura, fácil de percorrer a pé, com bom clima e muitas atividades culturais.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (102, 'If you could meet any famous person, who would you choose?', 'Se você pudesse conhecer qualquer pessoa famosa, quem escolheria?', '[{"answer":"I''d choose Barack Obama.","translation":"Eu escolheria Barack Obama.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I''d love to meet a famous musician I admire.","translation":"Eu adoraria conhecer um músico famoso que admiro.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I''d like to meet a scientist such as Neil deGrasse Tyson.","translation":"Eu gostaria de conhecer um cientista como Neil deGrasse Tyson.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I''d choose an actor I really like.","translation":"Eu escolheria um ator de quem gosto muito.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I''d probably meet someone whose work has influenced my career, so I could ask them questions.","translation":"Eu provavelmente conheceria alguém cujo trabalho influenciou minha carreira, para poder fazer perguntas.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (103, 'If you had a free day tomorrow, what would you do?', 'Se você tivesse um dia livre amanhã, o que faria?', '[{"answer":"I''d sleep a little longer.","translation":"Eu dormiria um pouco mais.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I''d spend the day with my family.","translation":"Eu passaria o dia com minha família.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I''d go somewhere outdoors.","translation":"Eu iria a algum lugar ao ar livre.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I''d watch movies and relax at home.","translation":"Eu assistiria a filmes e relaxaria em casa.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I''d have a slow morning, go out for lunch, and do something I normally don''t have time for.","translation":"Eu teria uma manhã tranquila, sairia para almoçar e faria algo para o qual normalmente não tenho tempo.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (104, 'What is something most people do not know about you?', 'O que é algo que a maioria das pessoas não sabe sobre você?', '[{"answer":"Most people don''t know that I can play the guitar.","translation":"A maioria das pessoas não sabe que eu sei tocar violão.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"People are often surprised that I enjoy cooking.","translation":"As pessoas frequentemente se surpreendem ao saber que eu gosto de cozinhar.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"Not many people know that I used to be very shy.","translation":"Poucas pessoas sabem que eu costumava ser muito tímido/a.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"Most people don''t know that I collect old books.","translation":"A maioria das pessoas não sabe que eu coleciono livros antigos.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"One thing people usually discover only after knowing me for a while is that I really enjoy writing.","translation":"Uma coisa que as pessoas geralmente só descobrem depois de me conhecer por um tempo é que eu gosto muito de escrever.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb)
)
update public.conversation_questions q set question_text=c.question_text,question_translation=c.question_translation,answer_examples=c.answer_examples from card_content c where q.display_order=c.display_order;
